B.aym=s(["\ud504\ub9ac\ub79c\uc11c\ub85c\uc11c \uc55e\uc73c\ub85c \uc5b4\ub5a8\uae4c\uc694?","\uc9c0\uae08 \uc774 \ud750\ub984\uc774 \uacc4\uc18d\ub420\uae4c\uc694?","\uc0c8\ub85c\uc6b4 \uae30\ud68c\uac00 \ucc3e\uc544\uc62c\uae4c\uc694?"],t.s)
B.azg=s(["\uc9c0\uae08 \ub2e4\ub2c8\ub294 \uc9c1\uc7a5, \uc548\uc804\ud560\uae4c\uc694?","\uc774 \ud68c\uc0ac\uc5d0 \uacc4\uc18d \ub2e4\ub140\ub3c4 \ub420\uae4c\uc694?","\uc55e\uc73c\ub85c \uc5b4\ub5a4 \ubcc0\ud654\uac00 \uc788\uc744\uae4c\uc694?"],t.s)
B.aFw=s(["\uc62c\ud574 \uc81c \ucee4\ub9ac\uc5b4 \ud750\ub984\uc774 \uc5b4\ub5a8\uae4c\uc694?","\uc62c\ud574 \uc911\uc694\ud55c \uc2dc\uae30\uac00 \uc5b8\uc81c\uc77c\uae4c\uc694?","\uc62c\ud574 \ub193\uce58\uba74 \uc548 \ub420 \uae30\ud68c\uac00 \uc788\uc744\uae4c\uc694?"],t.s)
B.aAo=s(["\uc800\uc5d0\uac8c \ub9de\ub294 \uc77c\uc740 \ubb58\uae4c\uc694?","\uc9c0\uae08 \ud558\ub294 \uc77c\uc774 \uc800\uc640 \uc798 \ub9de\uc744\uae4c\uc694?","\uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub098\uc544\uac00\uc57c \ud560\uae4c\uc694?"],t.s)
B.ax6=s(["\uc774\uc81c \ub9c9 \uc2dc\uc791\ud55c \uc77c, \uc798 \ub420\uae4c\uc694?","\ucd08\ubc18\uc5d0 \uc870\uc2ec\ud574\uc57c \ud560 \uac8c \uc788\uc744\uae4c\uc694?","\uc774 \uacbd\ub825\uc744 \uacc4\uc18d \uc774\uc5b4\uac00\ub3c4 \ub420\uae4c\uc694?"],t.s)
B.awO=s(["\uc694\uc998 \uc81c \uc7ac\ubb3c\uc6b4\uc740 \uc5b4\ub5a8\uae4c\uc694?","\ub3c8\uc774 \ub4e4\uc5b4\uc62c \ud750\ub984\uc77c\uae4c\uc694?","\uc9c0\uae08 \uc7ac\uc815 \uad00\ub9ac\uc5d0\uc11c \ubb58 \uc870\uc2ec\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.aDy=s(["\uc694\uc998 \uc81c \uc18c\ube44 \ud328\ud134, \ubb38\uc81c \uc5c6\uc744\uae4c\uc694?","\ub3c8\uc774 \uc5b4\ub514\uc11c \uc0c8\uace0 \uc788\uc744\uae4c\uc694?","\uc18c\ube44\ub97c \uc5b4\ub5bb\uac8c \uc904\uc5ec\uc57c \ud560\uae4c\uc694?"],t.s)
B.aCr=s(["\uc9c0\uae08 \uc774 \ud22c\uc790, \ud574\ub3c4 \ub420\uae4c\uc694?","\uc774 \ud22c\uc790\uac00 \uc88b\uc740 \ud750\ub984\uc77c\uae4c\uc694?","\uc9c0\uae08\uc774 \ud22c\uc790\ud558\uae30 \uc88b\uc740 \uc2dc\uae30\uc77c\uae4c\uc694?"],t.s)
B.atv=s(["\uc774 \uacc4\uc57d, \uc131\uc0ac\ub420 \uc218 \uc788\uc744\uae4c\uc694?","\uacc4\uc57d \uc870\uac74\uc774 \uc800\uc5d0\uac8c \uc720\ub9ac\ud560\uae4c\uc694?","\uc9c0\uae08 \uc9c4\ud589 \uc0c1\ud669\uc774 \uad1c\ucc2e\uc744\uae4c\uc694?"],t.s)
B.aEW=s(["\uae30\ub2e4\ub9ac\ub294 \ub3c8\uc774 \uc5b8\uc81c\ucbcd \ub4e4\uc5b4\uc62c\uae4c\uc694?","\uc9c0\uae08 \uc790\uae08 \ud750\ub984\uc774 \uc5b4\ub5a8\uae4c\uc694?","\uc5b8\uc81c \uc5ec\uc720\uac00 \uc0dd\uae38\uae4c\uc694?"],t.s)
B.aFE=s(["\uc9c0\uae08 \uc870\uc2ec\ud574\uc57c \ud560 \uc9c0\ucd9c\uc774 \uc788\uc744\uae4c\uc694?","\ub3c8\uc774 \uc0c8\uc5b4\ub098\uac08 \uc704\ud5d8\uc774 \uc788\uc744\uae4c\uc694?","\uc5b4\ub5a4 \ubd80\ubd84\uc744 \ub300\ube44\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.auo=s(["\uc9c0\uae08 \uc774 \ub3c8 \ubb38\uc81c, \ud480\ub9b4 \uc218 \uc788\uc744\uae4c\uc694?","\ud574\uacb0\uc758 \uc2e4\ub9c8\ub9ac\uac00 \uc788\uc744\uae4c\uc694?","\uc5b4\ub5bb\uac8c \uc811\uadfc\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.azy=s(["\uc9c0\uae08 \uac00\uc9c4 \uc790\uc0b0, \uc5b4\ub5bb\uac8c \ud574\uc57c \ud560\uae4c\uc694?","\uc9c0\uae08 \uc62e\uae30\ub294 \uac8c \ub9de\uc744\uae4c\uc694?","\uc790\uc0b0 \uad00\ub9ac\uc5d0\uc11c \ubb58 \uc870\uc2ec\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.awe=s(["\uc9c0\uae08\uae4c\uc9c0 \ud55c \ub178\ub825, \uc5b8\uc81c \uacb0\uc2e4\uc744 \ub9fa\uc744\uae4c\uc694?","\uc218\ud655\uc758 \uc2dc\uae30\uac00 \ub2e4\uac00\uc624\uace0 \uc788\uc744\uae4c\uc694?","\uc9c0\uae08 \ubb58 \ub354 \uc900\ube44\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.aEA=s(["\uc624\ub298 \ud558\ub8e8\ub294 \uc5b4\ub5a8\uae4c\uc694?","\uc624\ub298 \uc870\uc2ec\ud574\uc57c \ud560 \uac8c \uc788\uc744\uae4c\uc694?","\uc624\ub298 \uc800\uc5d0\uac8c \ud544\uc694\ud55c \uba54\uc2dc\uc9c0\ub294 \ubb58\uae4c\uc694?"],t.s)
B.ayW=s(["\uc774\ubc88 \uc8fc \ud750\ub984\uc774 \uc5b4\ub5a8\uae4c\uc694?","\uc774\ubc88 \uc8fc \uc911\uc694\ud55c \ub0a0\uc774 \uc788\uc744\uae4c\uc694?","\uc774\ubc88 \uc8fc \ub193\uce58\uba74 \uc548 \ub420 \uae30\ud68c\uac00 \uc788\uc744\uae4c\uc694?"],t.s)
B.ayt=s(["\uc774\ubc88 \ub2ec \ud750\ub984\uc774 \uc5b4\ub5a8\uae4c\uc694?","\uc774\ubc88 \ub2ec \uc911\uc694\ud55c \uc804\ud658\uc810\uc774 \uc788\uc744\uae4c\uc694?","\uc774\ubc88 \ub2ec \ubb58 \uc900\ube44\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.avb=s(["\uc62c\ud574 \uc800\uc5d0\uac8c \uc5b4\ub5a4 \ud750\ub984\uc774 \uc788\uc744\uae4c\uc694?","\uc62c \ud55c \ud574 \uc911\uc694\ud55c \uc2dc\uae30\uac00 \uc5b8\uc81c\uc77c\uae4c\uc694?","\uc62c\ud574 \uc804\uccb4\uc801\uc73c\ub85c \uc5b4\ub5a4 \uba54\uc2dc\uc9c0\uac00 \uc788\uc744\uae4c\uc694?"],t.s)
B.azC=s(["\uc9c0\uae08 \uc800\uc5d0\uac8c \ud544\uc694\ud55c \uba54\uc2dc\uc9c0\uac00 \ubb58\uae4c\uc694?","\uc9c0\uae08 \uc81c\uac00 \ub193\uce58\uace0 \uc788\ub294 \uac8c \uc788\uc744\uae4c\uc694?","\uc9c0\uae08 \uc774 \uc0c1\ud669\uc5d0\uc11c \ubb58 \ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.asy=s(["\uc55e\uc73c\ub85c \uc870\uc2ec\ud574\uc57c \ud560 \uc77c\uc774 \uc788\uc744\uae4c\uc694?","\uc9c0\uae08 \uc81c\uac00 \uacbd\uacc4\ud574\uc57c \ud560 \uac8c \uc788\uc744\uae4c\uc694?","\uc5b4\ub5bb\uac8c \ub300\ucc98\ud558\uba74 \uc88b\uc744\uae4c\uc694?"],t.s)
B.aFp=s(["\uc9c0\uae08 \uc81c \ud589\uc6b4 \ud3ec\uc778\ud2b8\ub294 \ubb58\uae4c\uc694?","\uc5b4\ub514\uc5d0 \ud589\uc6b4\uc774 \uc228\uc5b4 \uc788\uc744\uae4c\uc694?","\ud589\uc6b4\uc744 \uc5b4\ub5bb\uac8c \ud65c\uc6a9\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.aFs=s(["A\uc640 B, \uc5b4\ub290 \ucabd\uc774 \ub354 \ub098\uc744\uae4c\uc694?","\ub450 \uc120\ud0dd\uc9c0 \uc911 \ubb58 \uace8\ub77c\uc57c \ud560\uae4c\uc694?","\uc774 \uc120\ud0dd, \uc5b4\ub5bb\uac8c \ube44\uad50\ud574\ubd10\uc57c \ud560\uae4c\uc694?"],t.s)
B.awx=s(["\ub0b4\uc77c\uc740 \uc5b4\ub5a4 \ud558\ub8e8\uac00 \ub420\uae4c\uc694?","\ub0b4\uc77c \uc870\uc2ec\ud574\uc57c \ud560 \uc21c\uac04\uc774 \uc788\uc744\uae4c\uc694?","\ub0b4\uc77c \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \uc900\ube44\ud558\uba74 \uc88b\uc744\uae4c\uc694?"],t.s)
B.aCo=s(["\uc55e\uc73c\ub85c \uc11d \ub2ec, \ud750\ub984\uc774 \uc5b4\ub5a8\uae4c\uc694?","\uc774 \ubd84\uae30\uc5d0 \uc911\uc694\ud55c \uc804\ud658\uc810\uc774 \uc788\uc744\uae4c\uc694?","\uc9c0\uae08\ubd80\ud130 \ubb58 \ub300\ube44\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.aEr=s(["\uc9c0\uae08 \uc81c \ub9c8\uc74c\uc774 \uc5b4\ub5a4 \uc0c1\ud0dc\uc77c\uae4c\uc694?","\uc81c\uac00 \uc228\uae30\uace0 \uc788\ub294 \uac10\uc815\uc774 \uc788\uc744\uae4c\uc694?","\uc774 \uac10\uc815\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\uace0 \uc788\uc744\uae4c\uc694?"],t.s)
B.aEF=s(["\uc9c0\uae08 \uc774 \ubd88\uc548, \uc65c \uc0dd\uae34 \uac78\uae4c\uc694?","\ubd88\uc548\uc758 \uc9c4\uc9dc \uc6d0\uc778\uc774 \ubb58\uae4c\uc694?","\uc5b4\ub5bb\uac8c \ud558\uba74 \uc548\uc815\uc744 \ucc3e\uc744 \uc218 \uc788\uc744\uae4c\uc694?"],t.s)
B.axb=s(["\uc9c0\uae08 \uc800\uc5d0\uac8c \ud544\uc694\ud55c \uc704\ub85c\uac00 \ubb58\uae4c\uc694?","\uc65c \uc774\ub807\uac8c \uc704\ub85c\uac00 \ud544\uc694\ud55c \uac78\uae4c\uc694?","\uc5b4\ub5bb\uac8c \ud558\uba74 \ub9c8\uc74c\uc774 \ud3b8\ud574\uc9c8\uae4c\uc694?"],t.s)
B.ava=s(["\uc9c0\uae08 \ub193\uc544\uc57c \ud560 \uac10\uc815\uc774 \uc788\uc744\uae4c\uc694?","\uc65c \uc774 \uac10\uc815\uc744 \ubd99\uc7a1\uace0 \uc788\ub294 \uac78\uae4c\uc694?","\uc5b4\ub5bb\uac8c \ud758\ub824\ubcf4\ub0b4\uc57c \ud560\uae4c\uc694?"],t.s)
B.aAZ=s(["\uc9c0\uae08 \ub2e4\uc2dc \uc2dc\uc791\ud560 \uc218 \uc788\uc744\uae4c\uc694?","\ub2e4\uc2dc \uc2dc\uc791\ud558\ub824\uba74 \ubb50\uac00 \ud544\uc694\ud560\uae4c\uc694?","\uc9c0\uae08\uc774 \ub2e4\uc2dc \uc77c\uc5b4\uc124 \ub54c\uc77c\uae4c\uc694?"],t.s)
B.aF_=s(["\uc9c0\uae08 \uc800\uc5d0\uac8c \ud544\uc694\ud55c \uc870\uc5b8\uc774 \ubb58\uae4c\uc694?","\uc81c\uac00 \ub193\uce58\uace0 \uc788\ub294 \uac8c \uc788\uc744\uae4c\uc694?","\uc2a4\uc2a4\ub85c\uc5d0\uac8c \uc5b4\ub5a4 \ub9d0\uc744 \ud574\uc918\uc57c \ud560\uae4c\uc694?"],t.s)
B.aAP=s(["\uc81c \uc548\uc5d0 \uc228\uc740 \uc7ac\ub2a5\uc774 \uc788\uc744\uae4c\uc694?","\uc544\uc9c1 \ubc1c\uacac \ubabb\ud55c \uac15\uc810\uc774 \uc788\uc744\uae4c\uc694?","\uc774 \uc7ac\ub2a5\uc744 \uc5b4\ub5bb\uac8c \ubc1c\uacac\ud574\uc57c \ud560\uae4c\uc694?"],t.s)
B.aFP=s(["\uc9c0\uae08 \uc800\ub294 \uc5b4\ub5bb\uac8c \uc131\uc7a5\ud558\uace0 \uc788\uc744\uae4c\uc694?","\uc131\uc7a5\uc744 \uc704\ud574 \ubb58 \ud574\uc57c \ud560\uae4c\uc694?","\uc55e\uc73c\ub85c \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub098\uc544\uac00\uc57c \ud560\uae4c\uc694?"],t.s)
B.ayb=s(["\uc9c0\uae08 \uc65c \uc774\ub807\uac8c \ub9c8\uc74c\uc774 \ud754\ub4e4\ub9b4\uae4c\uc694?","\uc774 \uac10\uc815\uc758 \ud30c\ub3d9, \uc5b8\uc81c \uac00\ub77c\uc549\uc744\uae4c\uc694?","\uc5b4\ub5bb\uac8c \ud558\uba74 \uc548\uc815\ub420 \uc218 \uc788\uc744\uae4c\uc694?"],t.s)
B.ay4=s(["\uc81c \ub9c8\uc74c\uc774 \uc9c0\uae08 \uc5b4\ub514\uc5d0 \uba38\ubb3c\ub7ec \uc788\uc744\uae4c\uc694?","\uc65c \uc544\uc9c1 \uadf8\ub54c\uc5d0 \uba38\ubb3c\ub7ec \uc788\ub294 \uac78\uae4c\uc694?","\uc5b4\ub5bb\uac8c \ud558\uba74 \ud604\uc7ac\ub85c \ub3cc\uc544\uc62c \uc218 \uc788\uc744\uae4c\uc694?"],t.s)
B.aCy=s(["\uc9c0\uae08 \uc81c \uc601\ud63c\uacfc \ub9de\ub2ff\uc740 \uce74\ub4dc\ub294 \ubb58\uae4c\uc694?","\uc774 \uce74\ub4dc\uac00 \uc804\ud558\ub294 \uba54\uc2dc\uc9c0\uac00 \ubb58\uae4c\uc694?","\uc9c0\uae08 \uc800\uc5d0\uac8c \ud544\uc694\ud55c \uc0b6\uc758 \ubc29\ud5a5\uc774 \ubb58\uae4c\uc694?"],t.s)
B.aC6=s(["\uc624\ub298 \uc800\ub97c \ucc3e\uc544\uc628 \uce74\ub4dc\ub294 \ubb58\uae4c\uc694?","\uc774 \uce74\ub4dc\uac00 \uc804\ud558\ub294 \uc6b4\uba85\uc801 \uc758\ubbf8\uac00 \ubb58\uae4c\uc694?","\uc624\ub298 \ud558\ub8e8, \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \uc9c0\ub0b4\uc57c \ud560\uae4c\uc694?"],t.s)
B.aA9=s(["\uc774 \uc0c8\ubcbd, \uc800\uc5d0\uac8c \ud544\uc694\ud55c \uba54\uc2dc\uc9c0\uac00 \ubb58\uae4c\uc694?","\uc65c \uc7a0\ub4e4\uc9c0 \ubabb\ud558\uace0 \uc788\ub294 \uac78\uae4c\uc694?","\uc9c0\uae08 \ub9c8\uc74c\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub3c5\uc5ec\uc57c \ud560\uae4c\uc694?"],t.s)
B.aB6=s(["\uc624\ub298 \ubcf4\ub984\ub2ec\uc774 \uc800\uc5d0\uac8c \ube44\ucd94\ub294 \uac74 \ubb58\uae4c\uc694?","\uc9c0\uae08 \uac10\ucdb0\uc9c4 \uac8c \ub4dc\ub7ec\ub0a0\uae4c\uc694?","\uc55e\uc73c\ub85c \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub098\uc544\uac00\uc57c \ud560\uae4c\uc694?"],t.s)
B.aDf=s(["\uc81c \uc18c\uc6d0\uc774 \uc774\ub8e8\uc5b4\uc9c8 \uc218 \uc788\uc744\uae4c\uc694?","\uc18c\uc6d0\uc744 \uc774\ub8e8\uae30 \uc704\ud574 \ubb50\uac00 \ud544\uc694\ud560\uae4c\uc694?","\uc9c0\uae08 \uc18c\uc6d0\uc5d0 \uc9d1\uc911\ud574\ub3c4 \ub420\uae4c\uc694?"],t.s)
B.awX=s(["\uc9c0\uae08 \uc5f4\ub9ac\ub294 \ubb38 \ub108\uba38\uc5d4 \ubb50\uac00 \uc788\uc744\uae4c\uc694?","\uc774 \uae30\ud68c\uc758 \ubb38, \uc5f4\uc5b4\ub3c4 \ub420\uae4c\uc694?","\ubb38\uc744 \uc5f4\ub824\uba74 \ubb50\uac00 \ud544\uc694\ud560\uae4c\uc694?"],t.s)
B.az4=s(["\uc774 \uc5bd\ud78c \uc778\uc5f0, \uc5b4\ub5bb\uac8c \ud480\uc5b4\uc57c \ud560\uae4c\uc694?","\uc9c0\uae08 \uc800\ub294 \uc5b4\ub514\ucbcd \uc11c \uc788\ub294 \uac78\uae4c\uc694?","\uc774 \ubbf8\ub85c\ub97c \ube60\uc838\ub098\uac08 \ubc29\ubc95\uc774 \uc788\uc744\uae4c\uc694?"],t.s)
B.at9=s(["\uc81c \ub9c8\uc74c\uc18d \uc815\uc6d0\uc774 \uc804\ud558\ub294 \uba54\uc2dc\uc9c0\uac00 \ubb58\uae4c\uc694?","\uc81c\uac00 \uac10\ucdb0\ub454 \uac8c \uc788\uc744\uae4c\uc694?","\uc55e\uc73c\ub85c \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub098\uc544\uac00\uc57c \ud560\uae4c\uc694?"],t.s)
