B.ayp=s(["{n}\ub2d8\uacfc {me}\ub2d8\uc740 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \uc11c\ub85c\ub97c \uc0b4\ub9ac\ub3c4\ub85d \ub9de\ubb3c\ub9b0 \uc778\uc5f0\uc774\uc5d0\uc694. \ub450 \uc0ac\ub78c\uc758 \uc77c\uac04 \uc624\ud589\uc774 \uc0c1\uc0dd\uc758 \ubc29\ud5a5\uc73c\ub85c \ud750\ub974\uace0, \uc77c\uc9c0\uac00 \ud569\uc744 \uc774\ub8e8\uace0 \uc788\uc5b4\uc11c \ud568\uaed8 \uc788\uc744 \ub54c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc11c\ub85c\uc758 \uc88b\uc740 \uba74\uc774 \ub4dc\ub7ec\ub098\uc694.",'\uc774 \uad00\uacc4\uc758 \uac00\uc7a5 \ud070 \ud2b9\uc9d5\uc740 "\uc788\ub294 \uadf8\ub300\ub85c \uc778\uc815\ubc1b\ub294 \ub290\ub08c"\uc774\uc5d0\uc694. {me}\ub2d8\uc774 \uc2a4\uc2a4\ub85c\ub3c4 \uc798 \ubaa8\ub974\ub358 \uc7ac\ub2a5\uc774\ub098 \uac00\ub2a5\uc131\uc744 {n}\ub2d8\uc774 \uba3c\uc800 \uc54c\uc544\ubcf4\uace0, \ub9d0\uc5c6\uc774 \uae38\uc744 \uc5f4\uc5b4 \uc8fc\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544\uc694. \ubc18\ub300\ub85c {me}\ub2d8\uc758 \uc874\uc7ac\uac00 {n}\ub2d8\uc5d0\uac8c \uc548\uc815\uacfc \ud655\uc2e0\uc744 \uc918\uc694.',"\ucf00\ubbf8 \uc810\uc218\uac00 \ub192\uac8c \ub098\uc628 \uac83\uc740 \ub2e8\uc21c\ud788 \uc798 \ub9de\ub294\ub2e4\ub294 \ub73b\uc744 \ub118\uc5b4, \uc11c\ub85c\uc758 \uc778\uc0dd \ud750\ub984\uc5d0 \uc2e4\uc81c\ub85c \uc88b\uc740 \uc601\ud5a5\uc744 \uc8fc\uace0\ubc1b\ub294 \uad6c\uc870\ub77c\ub294 \ub73b\uc774\uc5d0\uc694. \uc624\ub798 \uc774\uc5b4\uc9c8\uc218\ub85d \uadf8 \ud798\uc774 \ub354 \ucee4\uc9c0\ub294 \uad00\uacc4\uc608\uc694."],t.s)
B.ayP=s(["\ucc98\uc74c \ub9cc\ub0ac\uc744 \ub54c \ubb18\ud558\uac8c \ud3b8\uc548\ud588\uac70\ub098, \uc624\ub798 \uc54c\ub358 \uc0ac\ub78c\ucc98\ub7fc \ub290\uaef4\uc84c\uc744 \uac00\ub2a5\uc131\uc774 \ucee4\uc694. \uc77c\uc9c0\uc758 \ud569\uc740 \uccab \ub300\ud654\uc5d0\uc11c\ubd80\ud130 \uacbd\uacc4\uc2ec\uc744 \ub0ae\ucdb0 \uc8fc\ub294 \uae30\uc6b4\uc774\ub77c, \ub9d0\uc774 \uc798 \ud1b5\ud558\uace0 \uce68\ubb35\ub3c4 \uc5b4\uc0c9\ud558\uc9c0 \uc54a\uc544\uc694.",'\uc2dc\uac04\uc774 \uc9c0\ub098\uba74\uc11c "\uc774 \uc0ac\ub78c \uc55e\uc5d0\uc11c\ub294 \ub0b4\uac00 \uc870\uae08 \ub354 \ub098\uc740 \uc0ac\ub78c\uc774 \ub41c\ub2e4"\ub294 \ub290\ub08c\uc774 \ub4e4\uc5c8\ub2e4\uba74, \uadf8\uac8c \ubc14\ub85c \ucc9c\uc0dd\uadc0\uc778\uc758 \uc2e0\ud638\uc608\uc694.'],t.s)
B.azU=s(["{n}\ub2d8\uc758 \uae30\uc6b4\uc740 {me}\ub2d8\uc758 \uc77c\uac04\uc744 \uc0dd(\u751f)\ud574 \uc8fc\ub294 \ubc29\ud5a5\uc73c\ub85c \ud758\ub7ec\uc694. \uc27d\uac8c \ub9d0\ud558\uba74 {n}\ub2d8 \uacc1\uc5d0 \uc788\uc744 \ub54c {me}\ub2d8\uc758 \uc5d0\ub108\uc9c0\uac00 \ucc44\uc6cc\uc9c0\uace0, \uc9c0\uccd0 \uc788\ub358 \ub9c8\uc74c\uc774 \ud68c\ubcf5\ub418\ub294 \uad6c\uc870\uc608\uc694.","\ub610\ud55c {me}\ub2d8\uc5d0\uac8c \ubd80\uc871\ud55c \uc624\ud589\uc744 {n}\ub2d8\uc774 \ub109\ub109\ud788 \uac00\uc9c0\uace0 \uc788\uc5b4\uc11c, \ud63c\uc790\uc11c\ub294 \uc798 \uc548 \ud480\ub9ac\ub358 \uc77c\uc774 {n}\ub2d8\uacfc \ud568\uaed8\ud558\uba74 \ub9e4\ub044\ub7fd\uac8c \ud480\ub9ac\ub294 \uacbd\ud5d8\uc744 \uc790\uc8fc \ud558\uac8c \ub3fc\uc694. \uacb0\uc815\uc774 \uc5b4\ub824\uc6b8 \ub54c, \uc0c8\ub85c\uc6b4 \ucd9c\ubc1c\uc744 \uc55e\ub480\uc744 \ub54c \ud2b9\ud788 \uc774 \ubcf4\uc644\uc758 \ud798\uc774 \ud06c\uac8c \uc791\uc6a9\ud574\uc694."],t.s)
B.awc=s(["\ub450 \uc0ac\ub78c\uc758 \uc77c\uc9c0(\ud0dc\uc5b4\ub09c \ub0a0\uc758 \uc9c0\uc9c0)\ub294 \uc721\ud569\uc744 \uc774\ub904\uc694. \uc77c\uc9c0\ub294 \ub9c8\uc74c \uae4a\uc740 \uacf3, \uac00\uc7a5 \uac00\uae4c\uc6b4 \uad00\uacc4\uc5d0\uc11c \ub4dc\ub7ec\ub098\ub294 \uc131\ud5a5\uc744 \ub73b\ud558\ub294\ub370, \uc774\uac83\uc774 \ud569\uc744 \uc774\ub8ec\ub2e4\ub294 \uac74 \uc18d\ub9c8\uc74c\uc758 \uacb0\uc774 \uc11c\ub85c \uc798 \ub9de\ubb3c\ub9b0\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694.","\uadf8\ub798\uc11c \uc0ac\uc18c\ud55c \uc624\ud574\uac00 \uc0dd\uaca8\ub3c4 \uc624\ub798\uac00\uc9c0 \uc54a\uace0, \ub2e4\uc2dc \ub9cc\ub098\uba74 \uae08\uc138 \uc6d0\ub798\uc758 \uc628\ub3c4\ub85c \ub3cc\uc544\uc640\uc694. \uac00\uae4c\uc6cc\uc9c8\uc218\ub85d \ud3b8\uc548\ud574\uc9c0\ub294, \ub4dc\ubb38 \uad00\uacc4\uc608\uc694."],t.s)
B.ayX=s(['{n}\ub2d8\uc740 {me}\ub2d8\uc5d0\uac8c "\uba3c\uc800 \uae38\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc0ac\ub78c"\uc758 \uc5ed\ud560\uc744 \ud574\uc694. \uc870\uc5b8\uc774 \ub0a0\uce74\ub86d\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc815\ud655\ud558\uace0, \ud544\uc694\ud55c \uc21c\uac04\uc5d0 \ud544\uc694\ud55c \uc0ac\ub78c\uc744 \uc5f0\uacb0\ud574 \uc8fc\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544\uc694.','{me}\ub2d8\uc740 {n}\ub2d8\uc5d0\uac8c "\ubbff\uace0 \uae30\ub308 \uc218 \uc788\ub294 \uc0ac\ub78c"\uc774\uc5d0\uc694. {n}\ub2d8\uc774 \ud754\ub4e4\ub9b4 \ub54c {me}\ub2d8\uc758 \ud55c\ub9c8\ub514\uac00 \uc911\uc2ec\uc744 \uc7a1\uc544 \uc918\uc694. \ud55c\ucabd\ub9cc \uc8fc\ub294 \uad00\uacc4\uac00 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc8fc\uace0\ubc1b\ub294 \uade0\ud615\uc774 \uc788\uc5b4\uc694.'],t.s)
B.aDL=s(["\uc0c8\ub85c\uc6b4 \uc77c\uc744 \uc2dc\uc791\ud558\uac70\ub098 \ubc29\ud5a5\uc744 \ubc14\uafc0 \ub54c \ud568\uaed8 \uc758\ub17c\ud558\uba74 \uc88b\uc544\uc694. \uacf5\ubd80, \uc774\uc9c1, \ucc3d\uc5c5, \uc774\uc0ac\ucc98\ub7fc \uc778\uc0dd\uc758 \ud070 \uacb0\uc815 \uc55e\uc5d0\uc11c {n}\ub2d8\uc758 \uc2dc\uc120\uc740 \ud070 \ub3c4\uc6c0\uc774 \ub3fc\uc694.","\ud568\uaed8 \uc5ec\ud589\uc744 \uac00\uac70\ub098 \uc624\ub798 \uba38\ubb34\ub294 \uacbd\ud5d8\uc744 \ub098\ub204\uba74 \uad00\uacc4\uac00 \ud55c\uce35 \uae4a\uc5b4\uc838\uc694. \uac19\uc740 \ubaa9\ud45c\ub97c \ub450\uace0 \ud611\ub825\ud560 \ub54c \ub450 \uc0ac\ub78c\uc758 \uc6b4\uc774 \ud568\uaed8 \uc62c\ub77c\uac00\uc694."],t.s)
B.auX=s(["\ub108\ubb34 \uc798 \ub9de\uae30 \ub54c\ubb38\uc5d0 \uc624\ud788\ub824 \uace0\ub9c8\uc6c0\uc744 \ud45c\ud604\ud558\ub294 \uac78 \uc78a\uae30 \uc26c\uc6cc\uc694. \ub2f9\uc5f0\ud558\uac8c \uc5ec\uae30\ub294 \uc21c\uac04 \uad00\uacc4\uc758 \uc628\ub3c4\uac00 \uc870\uae08\uc529 \ub0b4\ub824\uac08 \uc218 \uc788\uc5b4\uc694.","\ub610 {n}\ub2d8\uc5d0\uac8c \ubaa8\ub4e0 \uacb0\uc815\uc744 \uae30\ub300\ub824\ub294 \ub9c8\uc74c\uc774 \ucee4\uc9c0\uba74, {me}\ub2d8 \uc2a4\uc2a4\ub85c\uc758 \ud310\ub2e8\ub825\uc774 \uc57d\ud574\uc9c8 \uc218 \uc788\uc5b4\uc694. \uadc0\uc778\uc740 \uae38\uc744 \ube44\ucdb0 \uc8fc\ub294 \uc0ac\ub78c\uc774\uc9c0 \ub300\uc2e0 \uac78\uc5b4 \uc8fc\ub294 \uc0ac\ub78c\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud574 \uc8fc\uc138\uc694."],t.s)
B.aEo=s(["\uc0c1\uc0dd","\uc721\ud569","\ubcf4\uc644","\uc2e0\ub8b0","\uc131\uc7a5"],t.s)
B.aBV=s(["\uc88b\uc740 \uc18c\uc2dd\uc774 \uc0dd\uae30\uba74 \uac00\uc7a5 \uba3c\uc800 {n}\ub2d8\uc5d0\uac8c \uc54c\ub824 \uc8fc\uc138\uc694","\uace0\ub9c8\uc6c0\uc740 \uad6c\uccb4\uc801\uc73c\ub85c \ub9d0\ud560\uc218\ub85d \uae4a\uc774 \uc804\ud574\uc838\uc694","\uc911\uc694\ud55c \uacb0\uc815 \uc804\uc5d0 \ud55c \ubc88\ucbe4 \uc758\uacac\uc744 \ubb3c\uc5b4\ubcf4\uc138\uc694","{n}\ub2d8\uc774 \ud798\ub4e4 \ub54c\ub294 \uc870\uc5b8\ubcf4\ub2e4 \uacc1\uc5d0 \uc788\uc5b4 \uc8fc\ub294 \uac83\uc774 \ub354 \ud070 \ud798\uc774 \ub3fc\uc694"],t.s)
B.asu=s(["\ubd04","\uc0c8\ub85c\uc6b4 \uacc4\ud68d\uc744 \ud568\uaed8 \uc138\uc6b0\uae30 \uc88b\uc740 \uc2dc\uae30\uc608\uc694. {n}\ub2d8\uc774 \uac74\ub124\ub294 \uc791\uc740 \uc81c\uc548\uc774 \ud070 \uae30\ud68c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aFy=s(["\uc5ec\ub984","\ud568\uaed8\ud558\ub294 \uc2dc\uac04\uc774 \ub298\uc5b4\ub098\uace0 \uad00\uacc4\uac00 \uac00\uc7a5 \ud65c\uae30\ub97c \ub760\uc5b4\uc694. \uac19\uc774 \ubb34\uc5b8\uac00\ub97c \ub9cc\ub4e4\uc5b4 \ubcf4\uc138\uc694."],t.s)
B.ath=s(["\uac00\uc744","\uadf8\ub3d9\uc548 \ud568\uaed8 \uc313\uc740 \uac83\uc774 \uacb0\uc2e4\uc744 \ub9fa\ub294 \ub54c\uc608\uc694. \uace0\ub9c8\uc6b4 \ub9c8\uc74c\uc744 \uaf2d \ub9d0\ub85c \uc804\ud574 \uc8fc\uc138\uc694."],t.s)
B.aAM=s(["\uaca8\uc6b8","\uc5f0\ub77d\uc774 \ub738\ud574\uc838\ub3c4 \uad00\uacc4\ub294 \ub2e8\ub2e8\ud574\uc694. \uc9e7\uc740 \uc548\ubd80 \ud558\ub098\uac00 \ub2e4\uc74c \ud574\uc758 \ud750\ub984\uc744 \uc88b\uac8c \uc5f4\uc5b4 \uc918\uc694."],t.s)
B.aw6=s([B.asu,B.aFy,B.ath,B.aAM],t.rj)
B.amO=new A.ug("\uc11c\ub85c\ub97c \ud06c\uac8c \uc774\ub04c\uc5b4 \uc8fc\ub294 \ud0c0\uace0\ub09c \uadc0\uc778",u.cK,B.ayp,B.ayP,B.azU,B.awc,B.ayX,B.aDL,B.auX,B.aEo,B.aBV,B.aw6)
B.aCX=s(["{n}\ub2d8\uacfc {me}\ub2d8\uc740 \uc77c\uc9c0\uac00 \ud569\uc744 \uc774\ub8e8\ub294 \uc778\uc5f0\uc774\uc5d0\uc694. \uc5b5\uc9c0\ub85c \ub178\ub825\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc11c\ub85c\uc5d0\uac8c \ub9c8\uc74c\uc774 \uac00\uace0, \uc2dc\uac04\uc774 \uc9c0\ub0a0\uc218\ub85d \uc815\uc774 \uae4a\uc5b4\uc9c0\ub294 \uad00\uacc4\uc608\uc694. \ud568\uaed8 \ubcf4\ub0b8 \ub0a0\ub4e4\uc774 \ud558\ub098\ub458 \uc313\uc774\uba74\uc11c \u201c\uc774 \uc0ac\ub78c\uc740 \ub0b4 \uc0ac\ub78c\u201d\uc774\ub77c\ub294 \ud655\uc2e0\uc774 \uc870\uc6a9\ud788 \uc790\ub77c\ub098\uc694.","\uc774 \uad00\uacc4\ub294 \ud654\ub824\ud558\uac8c \ud0c0\uc624\ub974\uae30\ubcf4\ub2e4 \uc740\uc740\ud558\uac8c \uc624\ub798 \uac00\uc694. \ud070 \uc0ac\uac74\uc774 \uc5c6\uc5b4\ub3c4 \uc77c\uc0c1\uc758 \uc791\uc740 \uc21c\uac04, \uac19\uc774 \uba39\uc740 \ubc25 \ud55c \ub07c\ub098 \ub2a6\uc740 \ubc24\uc758 \uc9e7\uc740 \ud1b5\ud654 \uac19\uc740 \uc7a5\uba74\uc5d0\uc11c \uc11c\ub85c\uc758 \uc18c\uc911\ud568\uc744 \ub290\ub07c\uac8c \ub3fc\uc694.","\ucf00\ubbf8 \uc810\uc218\uac00 \ubcf4\uc5ec\uc8fc\ub4ef \ub450 \uc0ac\ub78c\uc740 \uac10\uc815\uc758 \uacb0\uc774 \uc798 \ub9de\uc544\uc694. \ud55c\ucabd\uc774 \uc11c\uc6b4\ud55c \ub9c8\uc74c\uc744 \uaebc\ub0b4\uae30 \uc804\uc5d0 \ub2e4\ub978 \ucabd\uc774 \uba3c\uc800 \uc54c\uc544\ucc44\ub294 \uc77c\uc774 \ub9ce\uace0, \ub9d0\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc804\ud574\uc9c0\ub294 \uac83\uc774 \ub9ce\uc740 \uc0ac\uc774\uc608\uc694."],t.s)
B.aud=s(["\uccab \ub9cc\ub0a8\uc774 \ud2b9\ubcc4\ud558\uc9c0 \uc54a\uc558\ub354\ub77c\ub3c4, \uc5b4\ub290\uc0c8 \uc790\uc8fc \uc0dd\uac01\ub098\uace0 \uc5f0\ub77d\ud558\uac8c \ub418\ub294 \uc0ac\uc774\uc600\uc744 \uac70\uc608\uc694. \ud569\uc758 \uae30\uc6b4\uc740 \ucc9c\ucc9c\ud788 \uc2a4\uba70\ub4dc\ub294 \ubc29\uc2dd\uc73c\ub85c \uc791\ub3d9\ud574\uc11c, \uc815\uc2e0\uc744 \ucc28\ub824 \ubcf4\uba74 \uc774\ubbf8 \uac00\uae4c\uc6cc\uc838 \uc788\uc5b4\uc694.","\ud568\uaed8 \uc788\uc73c\uba74 \uc2dc\uac04\uc774 \ube68\ub9ac \uac00\uace0, \ud5e4\uc5b4\uc9c4 \ub4a4\uc5d0\ub3c4 \ub300\ud654\uac00 \uc624\ub798 \ub9c8\uc74c\uc5d0 \ub0a8\ub294 \ub290\ub08c\uc774 \uc788\uc5b4\uc694. \ucc98\uc74c\ubd80\ud130 \ud3b8\ud588\ub2e4\uba74 \uadf8\uac74 \uc6b0\uc5f0\uc774 \uc544\ub2c8\ub77c \ub450 \uc0ac\ub78c\uc758 \uc77c\uc9c0\uac00 \uc11c\ub85c\ub97c \ub04c\uc5b4\ub2f9\uae34 \uacb0\uacfc\uc608\uc694."],t.s)
B.awU=s(["\ub450 \uc0ac\ub78c\uc758 \uc77c\uac04\uc740 \uc11c\ub85c\ub97c \ud06c\uac8c \ud574\uce58\uc9c0 \uc54a\uc73c\uba74\uc11c \ubd80\ub4dc\ub7fd\uac8c \ub9de\ubb3c\ub824\uc694. {me}\ub2d8\uc774 \ub4e4\ub730 \ub54c {n}\ub2d8\uc774 \ucc28\ubd84\ud788 \ubc1b\uc544 \uc8fc\uace0, {me}\ub2d8\uc774 \uac00\ub77c\uc549\uc744 \ub54c {n}\ub2d8\uc774 \uc628\uae30\ub97c \ub354\ud574 \uc8fc\ub294 \uc2dd\uc73c\ub85c \uac10\uc815\uc758 \ub192\ub0ae\uc774\uac00 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub9de\ucdb0\uc838\uc694.","\uc11c\ub85c \ubd80\uc871\ud55c \uc624\ud589\uc744 \uace0\ub974\uac8c \ucc44\uc6cc \uc8fc\ub294 \uad6c\uc870\ub77c\uc11c, \ud568\uaed8 \uc788\uc744 \ub54c \ub9c8\uc74c\uc758 \uade0\ud615\uc774 \uc798 \uc7a1\ud600\uc694. \ud63c\uc790\uc77c \ub54c\ub294 \uc27d\uac8c \uc9c0\uce58\ub358 \uc77c\ub3c4 {n}\ub2d8\uacfc \ud568\uaed8\ub77c\uba74 \ub35c \ubc84\uac81\uac8c \ub290\uaef4\uc9c8 \uac70\uc608\uc694."],t.s)
B.axd=s(["\uc77c\uc9c0\uc758 \uc721\ud569\uc740 \uac00\uc7a5 \uac00\uae4c\uc6b4 \uc790\ub9ac\uc5d0\uc11c \ub4dc\ub7ec\ub098\ub294 \ub9c8\uc74c\uc774 \uc798 \ub9de\ub294\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \uadf8\ub798\uc11c \uc11c\uc6b4\ud55c \uc77c\uc774 \uc0dd\uaca8\ub3c4 \uae08\ubc29 \ud480\ub9ac\uace0, \ub2e4\uc2dc \ub9cc\ub098\uba74 \uc544\ubb34 \uc77c \uc5c6\uc5c8\ub358 \uac83\ucc98\ub7fc \uc6c3\uac8c \ub3fc\uc694.","\uc9c0\uc9c0 \uc0ac\uc774\uc5d0 \ud569\uc774 \uc5ec\ub7ec \ubc88 \ub098\ud0c0\ub098\uc11c, \ud568\uaed8\ud558\ub294 \uc2dc\uac04\uc774 \uae38\uc5b4\uc9c8\uc218\ub85d \uacb0\uc18d\uc774 \ub2e8\ub2e8\ud574\uc838\uc694. \uc624\ub798 \ub5a8\uc5b4\uc838 \uc788\uc5b4\ub3c4 \ub2e4\uc2dc \ub9cc\ub098\uba74 \uae08\uc138 \uc608\uc804\uc758 \uc628\ub3c4\ub85c \ub3cc\uc544\uac00\ub294, \ub04a\uc5b4\uc9c0\uae30 \uc5b4\ub824\uc6b4 \ub048\uc774 \uc788\uc5b4\uc694."],t.s)
B.aFt=s(["{n}\ub2d8\uc740 {me}\ub2d8\uc5d0\uac8c \u201c\ub9c8\uc74c\uc744 \ud138\uc5b4\ub193\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\u201d\uc774\uc5d0\uc694. \ud310\ub2e8\ud558\uc9c0 \uc54a\uace0 \ub05d\uae4c\uc9c0 \ub4e4\uc5b4 \uc8fc\ub294 \ud798\uc774 \uc788\uc5b4\uc11c, \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uaebc\ub0b4\uc9c0 \ubabb\ud55c \uc774\uc57c\uae30\ub3c4 {n}\ub2d8 \uc55e\uc5d0\uc11c\ub294 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub098\uc640\uc694.","{me}\ub2d8\uc740 {n}\ub2d8\uc5d0\uac8c \u201c\ub3cc\uc544\uac08 \uacf3 \uac19\uc740 \uc0ac\ub78c\u201d\uc774\uc5d0\uc694. \uc5b4\ub514\uc11c \ubb34\uc5c7\uc744 \ud558\ub4e0 \ub9c8\uc9c0\ub9c9\uc5d4 \uc0dd\uac01\ub098\ub294 \uc0ac\ub78c, \ud798\ub4e0 \ud558\ub8e8 \ub05d\uc5d0 \uc5f0\ub77d\ud558\uace0 \uc2f6\uc740 \uc0ac\ub78c\uc774 \ubc14\ub85c {me}\ub2d8\uc774\uc5d0\uc694."],t.s)
B.awI=s(["\ud568\uaed8 \ubc25\uc744 \uba39\uace0, \uac77\uace0, \uc774\uc57c\uae30\ud558\ub294 \uc77c\uc0c1\uc758 \uc2dc\uac04\uc774 \uc774 \uad00\uacc4\uc758 \uac00\uc7a5 \ud070 \uc790\uc0b0\uc774\uc5d0\uc694. \ud2b9\ubcc4\ud55c \uacc4\ud68d\ubcf4\ub2e4 \uc790\uc8fc, \ud3b8\ud558\uac8c \ub9cc\ub098\ub294 \uac83\uc774 \ub354 \ud070 \ud798\uc774 \ub3fc\uc694.","\uae30\ub150\uc77c\uc744 \ucc59\uae30\uac70\ub098 \uc791\uc740 \uc120\ubb3c\uc744 \uc8fc\uace0\ubc1b\uc73c\uba74 \uc815\uc774 \ub208\uc5d0 \ub744\uac8c \uae4a\uc5b4\uc838\uc694. \ud568\uaed8 \ucc0d\uc740 \uc0ac\uc9c4\uc744 \ub0a8\uae30\uace0 \uac00\ub054 \uaebc\ub0b4 \ubcf4\ub294 \uac83\ub3c4 \ub450 \uc0ac\ub78c\uc5d0\uac8c \uc798 \ub9de\ub294 \ubc29\ubc95\uc774\uc5d0\uc694."],t.s)
B.aCs=s(["\ud3b8\uc548\ud568\uc774 \uc775\uc219\ud568\uc73c\ub85c \ubc14\ub00c\uba74 \ud45c\ud604\uc774 \uc904\uc5b4\ub4e4 \uc218 \uc788\uc5b4\uc694. \ub9c8\uc74c\uc740 \uadf8\ub300\ub85c\uc5ec\ub3c4 \ub9d0\ud558\uc9c0 \uc54a\uc73c\uba74 \uc0c1\ub300\ub294 \ubaa8\ub97c \uc218 \uc788\uc73c\ub2c8, \uace0\ub9c8\uc6c0\uacfc \uc560\uc815\uc740 \uac00\ub054 \uc18c\ub9ac \ub0b4\uc5b4 \uc804\ud574 \uc8fc\uc138\uc694.","\uc11c\ub85c\uc5d0\uac8c \ub108\ubb34 \uae30\ub300\ub2e4 \ubcf4\uba74 \ub2e4\ub978 \uad00\uacc4\uac00 \uc18c\ud640\ud574\uc9c8 \uc218 \uc788\uc5b4\uc694. \ub450 \uc0ac\ub78c\ub9cc\uc758 \uc138\uacc4\ub3c4 \uc18c\uc911\ud558\uc9c0\ub9cc, \uac01\uc790\uc758 \uc2dc\uac04\uacfc \uc0ac\ub78c\ub4e4\ub3c4 \ud568\uaed8 \uc9c0\ucf1c \uc8fc\ub294 \uac83\uc774 \uad00\uacc4\ub97c \uc624\ub798 \uac00\uac8c \ud574\uc694."],t.s)
B.asw=s(["\uc721\ud569","\uc815","\ud3b8\uc548\ud568","\ucd94\uc5b5","\uc628\uae30"],t.s)
B.asH=s(["\uc790\uc8fc \uc5f0\ub77d\ud558\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\uc544\uc694. \ud568\uaed8\ud55c \uc2dc\uac04\uc744 \uae30\uc5b5\ud574 \uc8fc\uc138\uc694","\uc791\uc740 \uc57d\uc18d\uc744 \uafb8\uc900\ud788 \uc9c0\ucf1c \uc8fc\uc138\uc694","\uc11c\uc6b4\ud55c \ub9c8\uc74c\uc740 \uc313\uc544 \ub450\uc9c0 \ub9d0\uace0 \uac00\ubccd\uac8c \uaebc\ub0b4 \uc8fc\uc138\uc694","\uace0\ub9c8\uc6b4 \uc21c\uac04\uc744 \uc0ac\uc9c4\uc774\ub098 \uae00\ub85c \ub0a8\uaca8 \ubcf4\uc138\uc694"],t.s)
B.aAN=s(["\ubd04","\uc0c8\ub85c\uc6b4 \ucd94\uc5b5\uc744 \ub9cc\ub4e4\uae30 \uc88b\uc740 \uc2dc\uae30\uc608\uc694. \uac00\uae4c\uc6b4 \uacf3\uc774\ub77c\ub3c4 \ud568\uaed8 \ub5a0\ub098 \ubcf4\uc138\uc694."],t.s)
B.aE4=s(["\uc5ec\ub984","\uac10\uc815\uc774 \ud48d\uc131\ud574\uc9c0\ub294 \ub54c\uc608\uc694. \uc194\uc9c1\ud55c \ub9c8\uc74c\uc744 \ub098\ub204\uba74 \uad00\uacc4\uac00 \ud55c \ub2e8\uacc4 \uae4a\uc5b4\uc838\uc694."],t.s)
B.axE=s(["\uac00\uc744","\uc11c\ub85c\uc5d0\uac8c \uace0\ub9c8\uc6b4 \uc77c\uc774 \ub9ce\uc544\uc9c0\ub294 \uc2dc\uae30\uc608\uc694. \uc791\uc740 \uc120\ubb3c\ub85c \ub9c8\uc74c\uc744 \uc804\ud574 \ubcf4\uc138\uc694."],t.s)
B.av4=s(["\uaca8\uc6b8","\uc870\uc6a9\ud788 \uacc1\uc744 \uc9c0\ucf1c \uc8fc\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub530\ub73b\ud55c \uacc4\uc808\uc774\uc5d0\uc694."],t.s)
B.aDg=s([B.aAN,B.aE4,B.axE,B.av4],t.rj)
B.amM=new A.ug("\uc790\uc5f0\uc2a4\ub7fd\uac8c \ub04c\ub9ac\uace0 \uc815\uc774 \uae4a\uc5b4\uc9c0\ub294 \uc778\uc5f0",u.ab,B.aCX,B.aud,B.awU,B.axd,B.aFt,B.awI,B.aCs,B.asw,B.asH,B.aDg)
B.aCH=s(["{n}\ub2d8\uacfc {me}\ub2d8\uc740 \ud55c\ucabd\uc758 \uae30\uc6b4\uc774 \ub2e4\ub978 \ucabd\uc744 \uc0b4\ub9ac\uace0 \ud0a4\uc6cc \uc8fc\ub294 \uc0c1\uc0dd \uad00\uacc4\uc608\uc694. \ud568\uaed8 \uc788\uc73c\uba74 \uc131\uc7a5\uc758 \uc18d\ub3c4\uac00 \ub208\uc5d0 \ub744\uac8c \ube68\ub77c\uc9c0\ub294 \uc778\uc5f0\uc774\uc5d0\uc694.","\uc120\uc0dd\uacfc \uc81c\uc790, \uc120\ubc30\uc640 \ud6c4\ubc30\ucc98\ub7fc \uc11c\ub85c \ubc30\uc6b0\uace0 \uac00\ub974\uce58\ub294 \ud750\ub984\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc0dd\uaca8\uc694. \ub2e4\ub9cc \uadf8 \uc5ed\ud560\uc774 \uace0\uc815\ub418\uc9c0 \uc54a\uace0 \uc0c1\ud669\uc5d0 \ub530\ub77c \ubc14\ub00c\uc5b4\uc11c, \uc5b4\ub5a4 \ub0a0\uc740 {me}\ub2d8\uc774 \uc774\ub04c\uace0 \uc5b4\ub5a4 \ub0a0\uc740 {n}\ub2d8\uc774 \uc774\ub04c\uc5b4\uc694.","\ucf00\ubbf8 \uc810\uc218\ub294 \ub450 \uc0ac\ub78c\uc774 \ud568\uaed8\ud560 \ub54c \uc2e4\uc9c8\uc801\uc778 \ub3c4\uc6c0\uc774 \uc624\uac04\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \uae30\ubd84 \uc88b\uc740 \uc751\uc6d0\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0, \uc2e4\uc81c\ub85c \uc77c\uc774 \ud480\ub9ac\uace0 \uc2e4\ub825\uc774 \ub298\uc5b4\ub098\ub294 \uad00\uacc4\uc608\uc694."],t.s)
B.axp=s(["\ucc98\uc74c\uc5d4 \u201c\ubc30\uc6b8 \uc810\uc774 \ub9ce\uc740 \uc0ac\ub78c\u201d\uc774\ub77c\ub294 \uc778\uc0c1\uc774\uc5c8\uc744 \uac70\uc608\uc694. \ub300\ud654\ub97c \ub098\ub20c\uc218\ub85d \uc0c8\ub85c\uc6b4 \uad00\uc810\uc744 \uc5bb\uac8c \ub418\uace0, \ud5e4\uc5b4\uc9c4 \ub4a4\uc5d0\ub3c4 \uadf8 \uc0ac\ub78c\uc774 \ud55c \ub9d0\uc774 \uc790\uafb8 \ub5a0\uc62c\ub790\uc744 \uc218 \uc788\uc5b4\uc694.","\ud568\uaed8 \uc77c\ud558\uac70\ub098 \uacf5\ubd80\ud560 \ub54c \ud2b9\ud788 \ube5b\ub098\ub294 \uc778\uc5f0\uc774\uc5d0\uc694. \uac19\uc740 \ubaa9\ud45c \uc55e\uc5d0 \uc130\uc744 \ub54c \uc11c\ub85c\uc758 \uc7a5\uc810\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4dc\ub7ec\ub098\uc694."],t.s)
B.aDO=s(["{n}\ub2d8\uc758 \uc77c\uac04\uc774 {me}\ub2d8\uc758 \uc77c\uac04\uc744 \uc0dd(\u751f)\ud574 \uc8fc\ub294 \ud750\ub984\uc774\uc5d0\uc694. {me}\ub2d8\uc774 \ubb34\uc5b8\uac00\ub97c \uc2dc\uc791\ud560 \ub54c {n}\ub2d8\uc758 \ud55c\ub9c8\ub514 \uc9c0\uc9c0\uac00 \ud070 \ucd94\uc9c4\ub825\uc774 \ub418\uace0, \ub9dd\uc124\uc774\ub358 \uc77c\uc744 \uc2e4\ud589\uc73c\ub85c \uc62e\uae30\uac8c \ud574 \uc918\uc694.","\ubd80\uc871\ud55c \uc624\ud589\uc744 \uc77c\ubd80 \ucc44\uc6cc \uc8fc\uc5b4, \ud63c\uc790\uc11c\ub294 \ubc84\uac70\uc6e0\ub358 \uc77c\uc744 \ub05d\uae4c\uc9c0 \ud574\ub0b4\uac8c \ub3c4\uc640\uc918\uc694. \ud2b9\ud788 \uc2dc\uc791\uc740 \uc798\ud558\uc9c0\ub9cc \ub9c8\ubb34\ub9ac\uac00 \uc57d\ud558\uac70\ub098, \uacc4\ud68d\uc740 \ub9ce\uc9c0\ub9cc \uc2e4\ud589\uc774 \ub2a6\uc744 \ub54c {n}\ub2d8\uc758 \uae30\uc6b4\uc774 \uade0\ud615\uc744 \uc7a1\uc544 \uc918\uc694."],t.s)
B.azV=s(["\uc77c\uc9c0 \uc0ac\uc774\uc5d0 \ud070 \ucda9\ub3cc\uc774 \uc5c6\uc5b4\uc11c \uad00\uacc4\uac00 \uc548\uc815\uc801\uc73c\ub85c \ud758\ub7ec\uac00\uc694. \uac10\uc815\uc758 \ud30c\ub3c4\ubcf4\ub2e4\ub294 \uafb8\uc900\ud55c \uc2e0\ub8b0\uac00 \ubc14\ud0d5\uc774 \ub418\ub294 \uc0ac\uc774\uc608\uc694.","\uadf8\ub798\uc11c \uc27d\uac8c \ud754\ub4e4\ub9ac\uc9c0 \uc54a\uc544\uc694. \ud55c\ub3d9\uc548 \uc5f0\ub77d\uc774 \ub738\ud574\ub3c4 \ud544\uc694\ud560 \ub54c \ub2e4\uc2dc \uc190\uc744 \ub0b4\ubc00\uba74 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub294, \ubbff\uc74c\uc9c1\ud55c \uad00\uacc4\uc608\uc694."],t.s)
B.aCV=s(["{n}\ub2d8\uc740 {me}\ub2d8\uc758 \uac00\ub2a5\uc131\uc744 \ud0a4\uc6cc \uc8fc\ub294 \uc0ac\ub78c\uc774\uc5d0\uc694. {me}\ub2d8\uc774 \ubbf8\ucc98 \ubcf4\uc9c0 \ubabb\ud55c \uc7ac\ub2a5\uc744 \uba3c\uc800 \uc54c\uc544\ubcf4\uace0, \ub2e4\uc74c \ub2e8\uacc4\ub85c \ub098\uc544\uac08 \uc218 \uc788\uac8c \uae38\uc744 \ubcf4\uc5ec\uc918\uc694.","{me}\ub2d8\uc740 {n}\ub2d8\uc5d0\uac8c \ubcf4\ub78c\uc744 \uc8fc\ub294 \uc0ac\ub78c\uc774\uc5d0\uc694. {me}\ub2d8\uc774 \uc131\uc7a5\ud558\ub294 \ubaa8\uc2b5\uc744 \ubcf4\ub294 \uac83 \uc790\uccb4\uac00 {n}\ub2d8\uc5d0\uac8c \ud070 \uae30\uc068\uc774 \ub418\uace0, \uadf8 \uae30\uc068\uc774 \ub2e4\uc2dc {n}\ub2d8\uc744 \uc6c0\uc9c1\uc774\uac8c \ud574\uc694."],t.s)
B.axQ=s(["\uacf5\ubd80, \ud504\ub85c\uc81d\ud2b8, \uc6b4\ub3d9\ucc98\ub7fc \ubaa9\ud45c\uac00 \ubd84\uba85\ud55c \uc77c\uc744 \ud568\uaed8\ud558\uba74 \uc88b\uc544\uc694. \uc11c\ub85c\uc758 \uc9c4\ub3c4\ub97c \ud655\uc778\ud558\uace0 \uc751\uc6d0\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc838\uc694.","\uc11c\ub85c\uc758 \uc131\uacfc\ub97c \ucd95\ud558\ud574 \uc8fc\ub294 \uc2b5\uad00\uc774 \uad00\uacc4\ub97c \ub354 \ub2e8\ub2e8\ud558\uac8c \ub9cc\ub4e4\uc5b4\uc694. \uc791\uc740 \uc131\ucde8\ub77c\ub3c4 \ud568\uaed8 \uae30\ubed0\ud574 \uc8fc\uc138\uc694."],t.s)
B.az_=s(["\uc8fc\ub294 \ucabd\uc774 \uc9c0\uce58\uc9c0 \uc54a\ub3c4\ub85d \uade0\ud615\uc744 \uc0b4\ud3b4 \uc8fc\uc138\uc694. \ud55c\ucabd\ub9cc \uacc4\uc18d \ub3c4\uc640\uc8fc\ub294 \uad00\uacc4\ub85c \ub290\uaef4\uc9c0\uba74 \ub9c8\uc74c\uc774 \uc870\uae08\uc529 \uba40\uc5b4\uc9c8 \uc218 \uc788\uc5b4\uc694.","\uc870\uc5b8\uc774 \uac04\uc12d\ucc98\ub7fc \ub4e4\ub9ac\uc9c0 \uc54a\uac8c, \uc0c1\ub300\uac00 \uc6d0\ud560 \ub54c \uac74\ub124\ub294 \uac83\uc774 \uc88b\uc544\uc694. \u201c\uc5b4\ub5bb\uac8c \uc0dd\uac01\ud574?\u201d\ub77c\uace0 \uba3c\uc800 \ubb3c\uc5b4\ubcf4\ub294 \uc791\uc740 \uc2b5\uad00\uc774 \ud070 \ucc28\uc774\ub97c \ub9cc\ub4e4\uc5b4\uc694."],t.s)
B.ayE=s(["\uc0c1\uc0dd","\uc131\uc7a5","\ubc30\uc6c0","\uc9c0\uc9c0","\ucd94\uc9c4\ub825"],t.s)
B.avX=s(["\uc11c\ub85c\uc758 \uc131\uc7a5\uc744 \uc751\uc6d0\ud558\ub294 \ub9d0 \ud55c\ub9c8\ub514\uac00 \ud070 \ud798\uc774 \ub3fc\uc694","\ubc1b\uc740 \ub3c4\uc6c0\uc740 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c\ub77c\ub3c4 \uaf2d \ub3cc\ub824\uc8fc\uc138\uc694","\uc0c8\ub85c\uc6b4 \ub3c4\uc804\uc744 \ud568\uaed8 \uacc4\ud68d\ud574 \ubcf4\uc138\uc694","\uc791\uc740 \uc131\uacfc\ub3c4 \ud568\uaed8 \ucd95\ud558\ud574 \uc8fc\uc138\uc694"],t.s)
B.axy=s(["\ubd04","\uc0c8\ub85c\uc6b4 \ub3c4\uc804\uc744 \ud568\uaed8 \uacc4\ud68d\ud558\uae30 \uc88b\uc740 \ub54c\uc608\uc694."],t.s)
B.aEO=s(["\uc5ec\ub984","\ub178\ub825\uc774 \uac00\uc7a5 \ube60\ub974\uac8c \uc131\uacfc\ub85c \uc774\uc5b4\uc9c0\ub294 \uc2dc\uae30\uc608\uc694. \ud568\uaed8 \uc18d\ub3c4\ub97c \ub0b4 \ubcf4\uc138\uc694."],t.s)
B.aw9=s(["\uac00\uc744","\ubc30\uc6b4 \uac83\uc744 \uc815\ub9ac\ud558\uace0 \ub098\ub204\uae30 \uc88b\uc740 \ub54c\uc608\uc694."],t.s)
B.ayY=s(["\uaca8\uc6b8","\ub2e4\uc74c \ud574\ub97c \uc704\ud55c \uc900\ube44\ub97c \ud568\uaed8 \uc774\uc57c\uae30\ud574 \ubcf4\uc138\uc694."],t.s)
B.aB4=s([B.axy,B.aEO,B.aw9,B.ayY],t.rj)
B.amP=new A.ug("\ud55c\ucabd\uc774 \ub2e4\ub978 \ucabd\uc744 \ud0a4\uc6cc \uc8fc\ub294 \uc0c1\uc0dd\uc758 \ub3d9\ud589",u.bY,B.aCH,B.axp,B.aDO,B.azV,B.aCV,B.axQ,B.az_,B.ayE,B.avX,B.aB4)
B.aF8=s(["{n}\ub2d8\uacfc {me}\ub2d8\uc740 \uc77c\uac04 \uc624\ud589\uc774 \uc11c\ub85c \uadf9\ud558\ub294 \uad00\uacc4\uc608\uc694. \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \ubd80\ub52a\ud788\uae30\ub3c4 \ud558\uc9c0\ub9cc, \uadf8\ub9cc\ud07c \uc11c\ub85c\ub97c \ub2e8\ub828\uc2dc\ud0a4\uace0 \uc131\uc7a5\ud558\uac8c \ub9cc\ub4dc\ub294 \uc778\uc5f0\uc774\uc5d0\uc694.","\ucc98\uc74c\uc5d4 \uc5b4\ub835\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\uc9c0\ub9cc, \uc870\uc728\ud558\ub294 \ubc95\uc744 \uc775\ud788\uba74 \ub204\uad6c\ubcf4\ub2e4 \uc11c\ub85c\ub97c \uae4a\uc774 \uc774\ud574\ud558\uac8c \ub3fc\uc694. \uc27d\uac8c \uc5bb\uc740 \uad00\uacc4\ubcf4\ub2e4 \ub2e4\ub4ec\uc5b4 \ub9cc\ub4e0 \uad00\uacc4\uac00 \ub354 \uc624\ub798 \uac00\ub294 \ubc95\uc774\uc5d0\uc694.","\uc810\uc218\uac00 \ub0ae\uc544 \ubcf4\uc5ec\ub3c4 \uc774 \uad00\uacc4\uac00 \ub098\uc058\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\uc5d0\uc694. \ub2e4\ub8f0 \uc904 \uc54c\uba74 \ud070 \ud798\uc774 \ub418\ub294 \uad00\uacc4\uc774\uace0, \uc11c\ub85c\uc758 \ube48\ud2c8\uc744 \uac00\uc7a5 \uc815\ud655\ud558\uac8c \uc9da\uc5b4 \uc8fc\ub294 \uc0ac\ub78c\uc774 \ub420 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aFj=s(["\uccab\uc778\uc0c1\uc774 \uac15\ub82c\ud588\uac70\ub098, \uc0dd\uac01\uc774 \ub9ce\uc774 \ub2e4\ub974\ub2e4\uace0 \ub290\uaf08\uc744 \uc218 \uc788\uc5b4\uc694. \uadf8\ub7f0\ub370\ub3c4 \uc774\uc0c1\ud558\uac8c \uc2e0\uacbd\uc774 \uc4f0\uc774\uace0 \uc790\uafb8 \ub208\uae38\uc774 \uac14\ub2e4\uba74, \uadf8\uac74 \uc11c\ub85c\uc5d0\uac8c \ud544\uc694\ud55c \ubb34\uc5b8\uac00\uac00 \uc788\ub2e4\ub294 \uc2e0\ud638\uc608\uc694.","\ucc98\uc74c \uba87 \ubc88\uc758 \ub300\ud654\uc5d0\uc11c \uc758\uacac\uc774 \uc5c7\uac08\ub838\ub354\ub77c\ub3c4, \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \u201c\uc774 \uc0ac\ub78c \ub9d0\uc5d0\ub3c4 \uc77c\ub9ac\uac00 \uc788\ub2e4\u201d\uace0 \ub290\ub07c\uac8c \ub418\ub294 \uad00\uacc4\uc608\uc694."],t.s)
B.awQ=s(["\ud55c\ucabd\uc758 \uae30\uc6b4\uc774 \ub2e4\ub978 \ucabd\uc744 \ub204\ub974\ub294 \ud750\ub984\uc774 \uc788\uc5b4\uc11c \uae34\uc7a5\uac10\uc774 \uc0dd\uaca8\uc694. {me}\ub2d8\uc774 \ubc00\uc5b4\ubd99\uc77c \ub54c {n}\ub2d8\uc774 \uc81c\ub3d9\uc744 \uac78\uac70\ub098, \uadf8 \ubc18\ub300\uc758 \uc0c1\ud669\uc774 \uc790\uc8fc \uc0dd\uae38 \uc218 \uc788\uc5b4\uc694.","\uadf8\ub798\ub3c4 \ubd80\uc871\ud55c \uc624\ud589\uc744 \uc870\uae08 \ucc44\uc6cc \uc8fc\ub294 \uba74\uc774 \uc788\uc5b4\uc11c, \uc11c\ub85c\uc5d0\uac8c \ud544\uc694\ud55c \uc790\uadf9\uc774 \ub3fc\uc694. \ud3b8\ud558\uae30\ub9cc \ud55c \uad00\uacc4\uc5d0\uc11c\ub294 \uc5bb\uc744 \uc218 \uc5c6\ub294 \uae68\ub2ec\uc74c\uc744 \uc8fc\ub294 \uc0ac\uc774\uc608\uc694."],t.s)
B.avC=s(["\uc77c\uc9c0 \uc0ac\uc774\uc5d0 \ub69c\ub837\ud55c \ud569\uc740 \uc5c6\uc9c0\ub9cc \ud070 \ucda9\ub3c4 \uc5c6\uc5b4\uc11c, \uac70\ub9ac\ub97c \uc798 \uc870\uc808\ud558\uba74 \uc548\uc815\uc801\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5b4\uc694.","\ub108\ubb34 \uac00\uae4c\uc774 \ubd99\uc5b4 \uc788\uc73c\uba74 \ubd80\ub52a\ud788\uace0, \ub108\ubb34 \uba40\uc5b4\uc9c0\uba74 \uc544\uc26c\uc6b4 \uad00\uacc4\uc608\uc694. \uc801\ub2f9\ud55c \uac70\ub9ac\ub97c \ucc3e\ub294 \uac83\uc774 \uc774 \uc778\uc5f0\uc744 \uc798 \uc9c0\ud0a4\ub294 \uc5f4\uc1e0\uc608\uc694."],t.s)
B.aDc=s(["\uad00\uc131 \uae30\uc6b4\uc774 \uac15\ud574\uc11c \ud55c\ucabd\uc774 \ub2e4\ub978 \ucabd\uc744 \uc774\ub04c\uac70\ub098 \ud1b5\uc81c\ud558\ub824\ub294 \ud750\ub984\uc774 \uc0dd\uae30\uae30 \uc26c\uc6cc\uc694. {n}\ub2d8\uc740 {me}\ub2d8\uc5d0\uac8c \u201c\uae30\uc900\uc744 \uc138\uc6cc \uc8fc\ub294 \uc0ac\ub78c\u201d\uc774 \ub420 \uc218 \uc788\uc5b4\uc694.","{me}\ub2d8\uc740 {n}\ub2d8\uc5d0\uac8c \u201c\ub2e4\ub978 \uc2dc\uac01\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc0ac\ub78c\u201d\uc774\uc5d0\uc694. \uc5ed\ud560\uc744 \ubd84\uba85\ud788 \ub098\ub204\uba74 \ubd80\ub52a\ud798\uc774 \ud06c\uac8c \uc904\uace0, \uc11c\ub85c\uc758 \ub2e4\ub984\uc774 \uc624\ud788\ub824 \uc7a5\uc810\uc73c\ub85c \ubc14\ub00c\uc5b4\uc694."],t.s)
B.aAv=s(["\uc77c\uc744 \ud560 \ub54c\ub294 \uc5ed\ud560\uc744 \ub098\ub204\uace0 \uac01\uc790\uc758 \uc601\uc5ed\uc744 \uc874\uc911\ud558\uba74 \uc88b\uc740 \uacb0\uacfc\uac00 \ub098\uc640\uc694. \ud55c \uc0ac\ub78c\uc774 \uae30\ud68d\ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc810\uac80\ud558\ub294 \uc2dd\uc758 \ubd84\uc5c5\uc774 \uc798 \ub9de\uc544\uc694.","\uc911\uc694\ud55c \uacb0\uc815\uc740 \ucda9\ubd84\ud788 \uc2dc\uac04\uc744 \ub450\uace0 \ud568\uaed8 \uac80\ud1a0\ud574 \ubcf4\uc138\uc694. \ub450 \uc0ac\ub78c\uc758 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uc120\uc774 \ub193\uce5c \ubd80\ubd84\uc744 \ucc44\uc6cc \uc918\uc694."],t.s)
B.aEw=s(["\uacb0\ub860\ubd80\ud130 \ub9d0\ud558\uae30\ubcf4\ub2e4 \uc774\uc720\ub97c \uba3c\uc800 \ub4e4\uc5b4 \uc8fc\uc138\uc694. \uac10\uc815\uc774 \uc62c\ub77c\uc62c \ub550 \uc7a0\uc2dc \uac70\ub9ac\ub97c \ub450\uace0, \ud558\ub8e8 \ub4a4\uc5d0 \ub2e4\uc2dc \uc774\uc57c\uae30\ud558\ub294 \uac83\uc774 \uc88b\uc544\uc694.","\uc0c1\ub300\ub97c \ubc14\uafb8\ub824 \ud558\uae30\ubcf4\ub2e4 \ub2e4\ub984\uc744 \uc778\uc815\ud558\ub294 \uac83\uc5d0\uc11c \uc2dc\uc791\ud574 \uc8fc\uc138\uc694. \uc774\uae30\ub824\ub294 \ub300\ud654\ubcf4\ub2e4 \uc774\ud574\ud558\ub824\ub294 \ub300\ud654\uac00 \uc774 \uad00\uacc4\ub97c \uc0b4\ub824\uc694."],t.s)
B.aEV=s(["\uc0c1\uadf9","\uc870\uc728","\ub2e8\ub828","\uac70\ub9ac","\uc874\uc911"],t.s)
B.auH=s(["\uc758\uacac\uc774 \ub2e4\ub97c \ub550 \uacb0\ub860\ubcf4\ub2e4 \uc774\uc720\ub97c \uba3c\uc800 \ub4e4\uc5b4 \uc8fc\uc138\uc694","\uac70\ub9ac\ub97c \uc870\uae08 \ub450\uba74 \uc624\ud788\ub824 \uad00\uacc4\uac00 \ud3b8\ud574\uc838\uc694","\uc5ed\ud560\uc744 \ub098\ub204\uba74 \ubd80\ub52a\ud798\uc774 \uc904\uc5b4\ub4e4\uc5b4\uc694","\uace0\ub9c8\uc6b4 \uc810\uc744 \uc758\uc2dd\uc801\uc73c\ub85c \ub9d0\ud574 \uc8fc\uc138\uc694"],t.s)
B.aCh=s(["\ubd04","\uc11c\ub85c\uc758 \uacc4\ud68d\uc744 \ubbf8\ub9ac \uacf5\uc720\ud558\uba74 \uc624\ud574\uac00 \uc904\uc5b4\uc694."],t.s)
B.ayr=s(["\uc5ec\ub984","\uac10\uc815\uc774 \uc27d\uac8c \ub2ec\uc544\uc624\ub974\ub294 \ub54c\ub77c \ub9d0\uc744 \uc544\uaef4 \uc8fc\uc138\uc694."],t.s)
B.aB8=s(["\uac00\uc744","\uadf8\ub3d9\uc548\uc758 \uc870\uc728\uc774 \uacb0\uc2e4\uc744 \ub9fa\ub294 \uc2dc\uae30\uc608\uc694."],t.s)
B.aAw=s(["\uaca8\uc6b8","\uc801\ub2f9\ud55c \uac70\ub9ac\uac00 \uc624\ud788\ub824 \uad00\uacc4\ub97c \ud3b8\ud558\uac8c \ud574\uc694."],t.s)
B.aw_=s([B.aCh,B.ayr,B.aB8,B.aAw],t.rj)
B.amN=new A.ug("\uae34\uc7a5\uacfc \uc870\uc728\uc774 \ud568\uaed8\ud558\ub294 \uad00\uacc4",u._,B.aF8,B.aFj,B.awQ,B.avC,B.aDc,B.aAv,B.aEw,B.aEV,B.auH,B.aw_)
B.aFJ=s(["{n}\ub2d8\uacfc {me}\ub2d8\uc740 \uc77c\uc9c0\uac00 \ucda9(\u6c96)\ud558\ub294 \uad00\uacc4\uc608\uc694. \ubd80\ub52a\ud798\uc774 \uc788\uc9c0\ub9cc, \uadf8 \ubd80\ub52a\ud798\uc774 \ub450 \uc0ac\ub78c\uc744 \ubcc0\ud654\uc2dc\ud0a4\uace0 \uc131\uc7a5\ud558\uac8c \ub9cc\ub4dc\ub294 \ub3d9\ub825\uc774 \ub3fc\uc694.","\ud3b8\ud558\uae30\ub9cc \ud55c \uad00\uacc4\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uc11c\ub85c\uc5d0\uac8c \uc5c6\ub294 \uac83\uc744 \uac00\uc9c0\uace0 \uc788\uc5b4\uc11c \ubc30\uc6b8 \uc810\uc774 \uc815\ub9d0 \ub9ce\uc544\uc694. \uc815\uccb4\ub41c \ud750\ub984\uc744 \uae68\uace0 \uc0c8\ub85c\uc6b4 \ubc29\ud5a5\uc744 \uc5f4\uc5b4 \uc8fc\ub294 \uc778\uc5f0\uc774\uc5d0\uc694.","\uc810\uc218\uac00 \ub0ae\uac8c \ub098\uc654\ub2e4\uace0 \uba40\ub9ac\ud560 \ud544\uc694\ub294 \uc5c6\uc5b4\uc694. \ucda9\uc740 \u201c\uc6c0\uc9c1\uc784\u201d\uc758 \uae30\uc6b4\uc774\ub77c, \uc798 \ub2e4\ub8e8\uba74 \uc778\uc0dd\uc758 \uc804\ud658\uc810\uc744 \ud568\uaed8 \ub9cc\ub4dc\ub294 \uc0ac\uc774\uac00 \ub420 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aFQ=s(["\ucc98\uc74c\ubd80\ud130 \uac15\ud55c \uc778\uc0c1\uc744 \ub0a8\uacbc\uac70\ub098, \uc758\uc678\uc758 \uc0c1\ud669\uc5d0\uc11c \uac11\uc790\uae30 \uac00\uae4c\uc6cc\uc84c\uc744 \uc218 \uc788\uc5b4\uc694. \uccab \ub9cc\ub0a8\uc774 \ud3c9\ubc94\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74 \uadf8\uac83\ub3c4 \ucda9\uc758 \uae30\uc6b4\uc774\uc5d0\uc694.","\ucc98\uc74c\uc5d4 \ub9de\uc9c0 \uc54a\ub294\ub2e4\uace0 \ub290\uaf08\ub294\ub370, \uc5b4\ub290 \uc21c\uac04 \uadf8 \uc0ac\ub78c\uc758 \ubc29\uc2dd\uc774 \uad81\uae08\ud574\uc9c0\uae30 \uc2dc\uc791\ud588\ub2e4\uba74 \uc774 \uad00\uacc4\uc758 \uac00\ub2a5\uc131\uc774 \uc5f4\ub9b0 \uac70\uc608\uc694."],t.s)
B.aAQ=s(["\ub450 \uc0ac\ub78c\uc740 \uc11c\ub85c \uc5c6\ub294 \uae30\uc6b4\uc744 \uac00\uc9c0\uace0 \uc788\uc5b4\uc11c \ud568\uaed8\ud558\uba74 \uc2dc\uc57c\uac00 \ub113\uc5b4\uc838\uc694. {me}\ub2d8\uc774 \ubbf8\ucc98 \uc0dd\uac01\ud558\uc9c0 \ubabb\ud55c \uae38\uc744 {n}\ub2d8\uc774 \ubcf4\uc5ec\uc8fc\uace0, \uadf8 \ubc18\ub300\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\uc608\uc694.","\uae30\uc6b4\uc774 \ubd80\ub52a\ud788\ub294 \uc21c\uac04\uc5d0\ub294 \uc5d0\ub108\uc9c0\uac00 \ud06c\uac8c \uc77c\uc5b4\ub098\uc694. \uc774 \uc5d0\ub108\uc9c0\ub97c \ub2e4\ud23c\uc774 \uc544\ub2c8\ub77c \uc0c8\ub85c\uc6b4 \uc2dc\ub3c4\uc5d0 \uc4f0\uba74, \ud63c\uc790\uc11c\ub294 \ubabb \ud588\uc744 \ubcc0\ud654\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc5b4\uc694."],t.s)
B.awB=s(["\uc77c\uc9c0\uc758 \ucda9\uc740 \uac00\uae4c\uc6b4 \uc790\ub9ac\uc5d0\uc11c \ubd80\ub52a\ud798\uc774 \uc0dd\uae30\uae30 \uc27d\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \ub108\ubb34 \uac00\uae4c\uc774 \ubd99\uc5b4 \uc788\uae30\ubcf4\ub2e4 \uc801\ub2f9\ud55c \uac70\ub9ac\ub97c \ub450\ub294 \uac83\uc774 \uad00\uacc4\ub97c \uc624\ub798 \uc9c0\ucf1c\uc694.","\ubd80\ub52a\ud78c \ub4a4\uc5d0 \ub2e4\uc2dc \ub3cc\uc544\uc624\ub294 \uacbd\ud5d8\uc774 \uc313\uc774\uba74, \uadf8\uac83\uc774 \uc624\ud788\ub824 \ub450 \uc0ac\ub78c\ub9cc\uc758 \ub2e8\ub2e8\ud55c \uc2e0\ub8b0\uac00 \ub3fc\uc694."],t.s)
B.azh=s(["{n}\ub2d8\uc740 {me}\ub2d8\uc5d0\uac8c \u201c\uc815\uccb4\ub41c \ud750\ub984\uc744 \uae68 \uc8fc\ub294 \uc0ac\ub78c\u201d\uc774\uc5d0\uc694. \uc775\uc219\ud568\uc5d0 \uba38\ubb3c\ub7ec \uc788\uc744 \ub54c \uc0c8\ub85c\uc6b4 \uc790\uadf9\uc744 \uc918\uc694.","{me}\ub2d8\uc740 {n}\ub2d8\uc5d0\uac8c \u201c\ub2e4\ub978 \uc138\uacc4\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc0ac\ub78c\u201d\uc774\uc5d0\uc694. \uc11c\ub85c\uc5d0\uac8c \uc790\uadf9\uc744 \uc8fc\uba70, \ud568\uaed8 \ubcc0\ud654\ud558\ub294 \uad00\uacc4\uc608\uc694."],t.s)
B.ax2=s(["\uc0c8\ub85c\uc6b4 \uc2dc\ub3c4\ub098 \ubcc0\ud654\uac00 \ud544\uc694\ud560 \ub54c \ud568\uaed8\ud558\uba74 \uc88b\uc544\uc694. \uc774\uc9c1, \uc774\uc0ac, \uc0c8\ub85c\uc6b4 \ub3c4\uc804\ucc98\ub7fc \ud750\ub984\uc744 \ubc14\uafb8\ub294 \uc21c\uac04\uc5d0 \uc11c\ub85c\uc758 \ud798\uc774 \ucee4\uc838\uc694.","\ud568\uaed8 \uc5ec\ud589\uc744 \uac00\uac70\ub098 \ub0af\uc120 \uacbd\ud5d8\uc744 \ud574 \ubcf4\uc138\uc694. \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \ud658\uacbd\uc5d0\uc11c \uc624\ud788\ub824 \ub450 \uc0ac\ub78c\uc758 \ud569\uc774 \uc798 \ub9de\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aEx=s(["\uac10\uc815\uc774 \uac00\ub77c\uc549\uc740 \ub4a4\uc5d0 \uc774\uc57c\uae30\ud574 \uc8fc\uc138\uc694. \ubd80\ub52a\ud78c \uadf8 \uc790\ub9ac\uc5d0\uc11c \uacb0\ub860\uc744 \ub0b4\ub824 \ud558\uba74 \uc0c1\ucc98\uac00 \uae4a\uc5b4\uc9c8 \uc218 \uc788\uc5b4\uc694.","\uc911\uc694\ud55c \uc77c\uc740 \uae00\ub85c \uc815\ub9ac\ud574 \uc624\ud574\ub97c \uc904\uc774\ub294 \uac83\uc774 \uc88b\uc544\uc694. \ub9d0\ubcf4\ub2e4 \uae00\uc774 \ub450 \uc0ac\ub78c \uc0ac\uc774\uc758 \uc628\ub3c4\ub97c \uc9c0\ucf1c \uc918\uc694."],t.s)
B.aEN=s(["\ucda9","\ubcc0\ud654","\uc790\uadf9","\uc131\uc7a5","\uadf9\ubcf5"],t.s)
B.ayu=s(["\ubd80\ub52a\ud798\uc740 \uc131\uc7a5\uc758 \uc2e0\ud638\uc608\uc694. \uac10\uc815\uc774 \uac00\ub77c\uc549\uc740 \ub4a4 \uc774\uc57c\uae30\ud574 \uc8fc\uc138\uc694","\uc11c\ub85c\uc758 \ub2e4\ub978 \uc810\uc744 \uc7a5\uc810\uc73c\ub85c \ubc14\ub77c\ubd10 \uc8fc\uc138\uc694","\uc911\uc694\ud55c \uc77c\uc740 \uae00\ub85c \uc815\ub9ac\ud574 \uc624\ud574\ub97c \uc904\uc5ec \uc8fc\uc138\uc694","\uac00\ub054\uc740 \uc801\ub2f9\ud55c \uac70\ub9ac\ub97c \ub450\uc5b4 \uc8fc\uc138\uc694"],t.s)
B.avI=s(["\ubd04","\ubcc0\ud654\ub97c \ud568\uaed8 \uc2dc\ub3c4\ud574 \ubcf4\uae30 \uc88b\uc740 \ub54c\uc608\uc694."],t.s)
B.atp=s(["\uc5ec\ub984","\ubd80\ub52a\ud798\uc774 \ucee4\uc9c8 \uc218 \uc788\uc73c\ub2c8 \ud55c \ubc15\uc790 \uc26c\uc5b4 \uac00\uc694."],t.s)
B.aC1=s(["\uac00\uc744","\uc11c\ub85c\uc758 \ub2e4\ub984\uc744 \uc778\uc815\ud558\uac8c \ub418\ub294 \uc2dc\uae30\uc608\uc694."],t.s)
